#!/usr/bin/env bash\nset -euo pipefail\n\n# Resolve the linter script location\nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)"\nLINTER="$SCRIPT_DIR/commit-lint.sh"\n\nrun_test() {\n  local name="$1"\n  local msg_file="$2"\n  local expect_exit="$3"\n  "$LINTER" "$msg_file"\n  local status=$?\n  if [[ $status -eq $expect_exit ]]; then\n    echo "PASS: $name"\n  else\n    echo "FAIL: $name (expected $expect_exit, got $status)"\n    exit 1\n  fi\n}\n\n# Create temporary directory for commit message fixtures\nTMPDIR=$(mktemp -d)\n\n# 1. Valid commit message\ncat >"$TMPDIR/good.txt" <<'EOF'\nfeat(parser): add new parsing logic\n\nImplemented support for nested structures.\nAll tests pass.\nEOF\n\n# 2. Subject line too long\ncat >"$TMPDIR/bad_len.txt" <<'EOF'\nfeat(parser): this subject line is definitely way too long and exceeds fifty characters\n\nSome body.\nEOF\n\n# 3. Missing Conventional Commits prefix\ncat >"$TMPDIR/bad_fmt.txt" <<'EOF'\nAdd new feature without type\n\nBody.\nEOF\n\n# 4. Body line too long\ncat >"$TMPDIR/bad_body.txt" <<'EOF'\nfeat: short subject\n\nThis body line is intentionally made very long to exceed the seventy-two character limit set for commit bodies.\nEOF\n\n# Execute tests\nrun_test "valid commit" "$TMPDIR/good.txt" 0\nrun_test "subject too long" "$TMPDIR/bad_len.txt" 1\nrun_test "bad format" "$TMPDIR/bad_fmt.txt" 1\nrun_test "body too long" "$TMPDIR/bad_body.txt" 1\n\necho "All tests passed."\nexit 0\n
